        private void RefreshServiceToggleLabels()
        {
            void UpdateToggle(Button? btn, string svcName, string labelEn, string labelRo)
            {
                if (btn == null) return;
                try
                {
                    using var sc = new System.ServiceProcess.ServiceController(svcName);
                    bool enabled = sc.StartType != System.ServiceProcess.ServiceStartMode.Disabled;
                    string state = enabled ? "ON" : "OFF";
                    // labelEn/labelRo are identical in all current calls (Windows service names — Win Update, SysMain, Win Search — are not
                    // translated), so labelEn is enough and correct for any language.
                    btn.Content    = labelEn + ": " + state;
                    // Subtle: transparent bg, colored border — not aggressive red fill
                    btn.Background  = (Brush)(TryFindResource("BgCardBrush") ?? new SolidColorBrush(WpfColor.FromArgb(30, 255, 255, 255)));
                    btn.Foreground  = enabled
                        ? new SolidColorBrush(WpfColor.FromRgb(34, 197, 94))
                        : new SolidColorBrush(WpfColor.FromRgb(148, 163, 184)); // slate — muted, not alarming
                    btn.BorderBrush = enabled
                        ? new SolidColorBrush(WpfColor.FromArgb(180, 34, 197, 94))
                        : new SolidColorBrush(WpfColor.FromArgb(120, 100, 116, 139));
                }
                catch
                {
                    btn.Content    = labelEn + ": ?";
                    btn.Background  = (Brush)(TryFindResource("BgCardBrush") ?? new SolidColorBrush());
                    btn.Foreground  = (Brush)(TryFindResource("TextSecondaryBrush") ?? new SolidColorBrush(WpfColor.FromRgb(100, 116, 139)));
                    btn.BorderBrush = (Brush)(TryFindResource("BorderBrush2") ?? new SolidColorBrush());
                }
            }

            UpdateToggle(BtnToggleUpdate,"wuauserv", "Win Update", "Win Update");
            UpdateToggle(BtnToggleSysMain,"SysMain","SysMain","SysMain");
            UpdateToggle(BtnToggleWinSearch, "WSearch","Win Search", "Win Search");

            // Also sync the ToggleSwitch CheckBoxes — by StartType, not Status.
            void SyncCheckBox(System.Windows.Controls.CheckBox? chk, string svcName)
            {
                if (chk == null) return;
                try
                {
                    using var sc = new System.ServiceProcess.ServiceController(svcName);
                    chk.IsChecked = sc.StartType != System.ServiceProcess.ServiceStartMode.Disabled;
                }
                catch { chk.IsChecked = null; }
            }
            SyncCheckBox(ChkWinUpdate,  "wuauserv");
            SyncCheckBox(ChkSysMain,    "SysMain");
            SyncCheckBox(ChkWinSearch,  "WSearch");
            SyncCheckBox(ChkTelemetry,  "DiagTrack");

            SyncBlockWinVersionButton();
        }

        private void SyncBlockWinVersionButton()
        {
            if (ChkBlockWinVersion == null) return;
            try
            {
                var (isBlocked, version, _) = GetWinVersionBlockState();
                ChkBlockWinVersion.IsChecked = isBlocked;
                if (TxtBlockWinVersionState != null)
                {
                    // the switch already shows On / Off; only the version Windows stays on appears here
                    TxtBlockWinVersionState.Text = isBlocked ? $"Blocked on {version}" : "";
                    TxtBlockWinVersionState.Visibility = isBlocked ? Visibility.Visible : Visibility.Collapsed;
                }
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }
        }

        /// <summary>Win Update ON/OFF — a full block in the WUB style (Services/WindowsUpdateBlocker): wuauserv + UsoSvc +
        /// WaaSMedicSvc disabled in the registry, without automatic re-enabling, with exact restore and a restore script in
        /// C:\ProgramData\SMDWin (works without SMD Win too). Disabling only wuauserv is not enough: Medic repairs it by itself.</summary>
        private async void ToggleWindowsUpdate_Click(object s, RoutedEventArgs e)
        {
            bool blocked = SMDWin.Services.WindowsUpdateBlocker.IsBlocked();
            if (!blocked)
            {
                bool go = AppDialog.Confirm(
                    "Turn off Windows Update completely?\n\n" +
                    "• Windows Update, Update Orchestrator and Update Medic will be disabled, so Windows can't switch them back on by itself.\n" +
                    "• While off, NO updates are installed — including security fixes. Turn it back on regularly.\n" +
                    "• A restore script is saved in " + SMDWin.Services.WindowsUpdateBlocker.MachineFolder +
                    " — it works even if SMD Win is no longer on this PC.",
                    "Windows Update");
                if (!go) { RefreshServiceToggleLabels(); return; }
            }

            var steps = await Task.Run(() => blocked
                ? SMDWin.Services.WindowsUpdateBlocker.Unblock()
                : SMDWin.Services.WindowsUpdateBlocker.Block());

            int okCount = steps.Count(x => x.Ok);
            bool criticalOk = steps.Where(x => x.Critical).All(x => x.Ok);
            var sb = new System.Text.StringBuilder();
            sb.AppendLine(blocked
                ? (criticalOk ? "Windows Update is back ON (original settings restored)." : "Windows Update could not be fully restored.")
                : (criticalOk ? "Windows Update is now OFF." : "Windows Update could not be fully turned off."));
            sb.AppendLine($"{okCount} of {steps.Count} steps succeeded:");
            sb.AppendLine();
            foreach (var st in steps)
                sb.AppendLine($"{(st.Ok ? "✓" : st.Critical ? "✗" : "–")}  {st.Step}{(st.Ok || st.Detail == null ? "" : "  (" + st.Detail + ")")}");
            if (!blocked && criticalOk)
            {
                sb.AppendLine();
                sb.AppendLine("To turn it back on without SMD Win, run:");
                sb.AppendLine(SMDWin.Services.WindowsUpdateBlocker.RestoreScript);
            }
            AppDialog.Show(sb.ToString().TrimEnd(), "Windows Update",
                criticalOk ? AppDialog.Kind.Success : AppDialog.Kind.Warning);

            RefreshServiceToggleLabels();
            if (PanelServices?.Visibility == Visibility.Visible)
                await ReloadServicesAsync();
        }
        private async void ToggleSysMain_Click      (object s, RoutedEventArgs e) => await ToggleServiceFull("SysMain",   isWindowsUpdate: false);
        private async void ToggleWindowsSearch_Click(object s, RoutedEventArgs e) => await ToggleServiceFull("WSearch",   isWindowsUpdate: false);

        private async void ToggleTelemetry_Click(object s, RoutedEventArgs e) => await ToggleTelemetryFull();

        private async Task ToggleTelemetryFull()
        {
            bool currentlyEnabled;
            try
            {
                using var sc = new System.ServiceProcess.ServiceController("DiagTrack");
                currentlyEnabled = sc.StartType != System.ServiceProcess.ServiceStartMode.Disabled;
            }
            catch { currentlyEnabled = true; }

            if (!ConfirmServiceChange(currentlyEnabled ? "Stop and disable" : "Enable and start", "Telemetry (DiagTrack, dmwappushservice)", "DiagTrack")) { RefreshServiceToggleLabels(); return; }
            if (currentlyEnabled)
            {
                await _svcService.StopServiceAsync("DiagTrack");
                await _svcService.SetServiceStartTypeAsync("DiagTrack", "Disabled");
                await _svcService.StopServiceAsync("dmwappushservice");
                await _svcService.SetServiceStartTypeAsync("dmwappushservice", "Disabled");
            }
            else
            {
                await _svcService.SetServiceStartTypeAsync("DiagTrack", "Automatic");
                await _svcService.StartServiceAsync("DiagTrack");
                await _svcService.SetServiceStartTypeAsync("dmwappushservice", "Automatic");
                await _svcService.StartServiceAsync("dmwappushservice");
            }

            RefreshServiceToggleLabels();
            if (PanelServices?.Visibility == Visibility.Visible)
                await ReloadServicesAsync();
        }

        private async Task ToggleServiceFull(string serviceName, bool isWindowsUpdate)
        {
            bool currentlyEnabled;
            try
            {
                using var sc = new System.ServiceProcess.ServiceController(serviceName);
                currentlyEnabled = sc.StartType != System.ServiceProcess.ServiceStartMode.Disabled;
            }
            catch { currentlyEnabled = true; }

            if (!ConfirmServiceChange(currentlyEnabled ? "Stop and disable" : "Enable and start", serviceName, serviceName)) { RefreshServiceToggleLabels(); return; }
            if (currentlyEnabled)
            {
                await _svcService.StopServiceAsync(serviceName);
                await _svcService.SetServiceStartTypeAsync(serviceName, "Disabled");
            }
            else
            {
                await _svcService.SetServiceStartTypeAsync(serviceName, "Automatic");
                await _svcService.StartServiceAsync(serviceName);
            }

            RefreshServiceToggleLabels();
            if (PanelServices?.Visibility == Visibility.Visible)
                await ReloadServicesAsync();
        }

        private (bool isBlocked, string version, string product) GetWinVersionBlockState()
        {
            string? displayVersion = Microsoft.Win32.Registry.GetValue(
                @"HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows NT\CurrentVersion",
                "DisplayVersion", null)?.ToString();
            string? productName = Microsoft.Win32.Registry.GetValue(
                @"HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows NT\CurrentVersion",
                "ProductName", null)?.ToString();
            string version = displayVersion ?? "24H2";
            string product = productName?.Contains("11") == true ? "Windows 11" : "Windows 10";

            const string keyPath = @"SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate";
            using var key = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(keyPath, writable: false);
            var currentVal = key?.GetValue("TargetReleaseVersionInfo")?.ToString();
            bool isBlocked = currentVal == version && key?.GetValue("TargetReleaseVersion") is int tv && tv == 1;
            return (isBlocked, version, product);
        }

        private void BlockCurrentWinVersion_Click(object s, RoutedEventArgs e)
        {
            try
            {
                var (isBlocked, version, product) = GetWinVersionBlockState();

                const string keyPath = @"SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate";
                using var key = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(keyPath, writable: true)
                             ?? Microsoft.Win32.Registry.LocalMachine.CreateSubKey(keyPath);

                if (isBlocked)
                {
                    // Unblock — full revert: deletes all 3 values set by Block, Windows Update offers the next version normally again.
                    key!.DeleteValue("TargetReleaseVersion", false);
                    key.DeleteValue("TargetReleaseVersionInfo", false);
                    key.DeleteValue("ProductVersion", false);
                    ShowToast(LanguageService.S("Msg", "WinVersionUnlocked"), "", 3500);
                }
                else
                {
                    // Block
                    key!.SetValue("TargetReleaseVersion",     1,       Microsoft.Win32.RegistryValueKind.DWord);
                    key.SetValue("TargetReleaseVersionInfo",  version,  Microsoft.Win32.RegistryValueKind.String);
                    key.SetValue("ProductVersion",            product,  Microsoft.Win32.RegistryValueKind.String);
                    ShowToast(string.Format(LanguageService.S("Msg", "WinVersionLockedFmt"), product, version), "", 4000);
                }
                SyncBlockWinVersionButton();
            }
            catch (Exception ex)
            {
                AppDialog.Show(string.Format(LanguageService.S("Msg", "GroupPolicyFailFmt"), ex.Message),
                    LanguageService.S("Msg", "WinVersionLockTitle"), AppDialog.Kind.Warning);
            }
        }

